import{_ as a,o as n,c as t,ao as r}from"./chunks/framework.8Icn9Cbp.js";const m=JSON.parse('{"title":"Internals","description":"","frontmatter":{},"headers":[],"relativePath":"internals.md","filePath":"internals.md","lastUpdated":null}'),s={name:"internals.md"};function l(i,e,p,o,h,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="Internals" tabindex="-1">Internals <a class="header-anchor" href="#Internals" aria-label="Permalink to &quot;Internals {#Internals}&quot;">​</a></h1><p>These pages document GEMB&#39;s non-exported internals: the physics kernels called by <a href="/GEMB.jl/previews/PR74/api#GEMB.gemb"><code>gemb</code></a>, the grid controllers, and the thermodynamic and hydrologic helpers.</p><p>They are <strong>not</strong> part of the public API. They are documented because the physics lives here — each scheme&#39;s docstring carries the citation for the law it implements — and because the narrative pages link to them. Their names and signatures may change in a minor release; depend on the public API in <a href="/GEMB.jl/previews/PR74/api#API-Reference">API Reference</a> instead.</p><p>The internals are split across three pages by subsystem:</p><ul><li><p><a href="/GEMB.jl/previews/PR74/internals_physics#Internals:-Physics">Internals: Physics</a> — the per-timestep physics kernels and their schemes</p></li><li><p><a href="/GEMB.jl/previews/PR74/internals_grid#Internals:-Grid-and-Column">Internals: Grid and Column</a> — grid controllers, layer management, profile setup</p></li><li><p><a href="/GEMB.jl/previews/PR74/internals_support#Internals:-Support">Internals: Support</a> — constants, metadata, interpolation, and other helpers</p></li></ul>',5)])])}const u=a(s,[["render",l]]);export{m as __pageData,u as default};
